    "Use a negative number to subtract": "Χρησιμοποιήστε αρνητικό αριθμό για αφαίρεση",
    "Calculate date": "Υπολογισμός ημερομηνίας",
    "Dates are calculated in your browser.": "Οι ημερομηνίες υπολογίζονται στο πρόγραμμα περιήγησής σας.",
    "Link or short text": "Σύνδεσμος ή σύντομο κείμενο",
    "Size": "Μέγεθος",
    "Always black and white for reliable scanning.": "Πάντα ασπρόμαυρο για αξιόπιστη σάρωση.",
    "Generate QR code": "Δημιουργία κωδικού QR",
    "Generated locally in your browser. Nothing is uploaded.": "Δημιουργείται τοπικά στο πρόγραμμα περιήγησής σας. Δεν γίνεται μεταφόρτωση δεδομένων.",
    "Download PNG": "Λήψη PNG",
    "Generated QR code": "Δημιουργημένος κωδικός QR",
    "Time zone": "Ζώνη ώρας",
