    "WCAG AA · normal text": "WCAG AA · κανονικό κείμενο",
    "WCAG AA · large text": "WCAG AA · μεγάλο κείμενο",
    "WCAG AAA · normal text": "WCAG AAA · κανονικό κείμενο",
    "Change either color to check readability. WCAG thresholds are guidance for this color pair only.": "Αλλάξτε ένα από τα δύο χρώματα για να ελέγξετε την αναγνωσιμότητα. Τα όρια WCAG αποτελούν κατευθυντήριες γραμμές μόνο για τον συγκεκριμένο συνδυασμό χρωμάτων.",
    "Bill amount": "Ποσό λογαριασμού",
    "Currency": "Νόμισμα",
    "Tip percentage": "Ποσοστό φιλοδωρήματος",
    "People": "Άτομα",
    "Tip total": "Συνολικό φιλοδώρημα",
    "Total with tip": "Σύνολο με φιλοδώρημα",
    "Tip per person": "Φιλοδώρημα ανά άτομο",
    "Total per person": "Σύνολο ανά άτομο",
    "Each person's share is rounded to your currency's smallest displayed unit.": "Το μερίδιο κάθε ατόμου στρογγυλοποιείται στη μικρότερη εμφανιζόμενη μονάδα του νομίσματός σας.",
    "Common US 4.0 scale. Your school may use different grade points.": "Συνηθισμένη κλίμακα 4,0 των ΗΠΑ. Το σχολείο σας ενδέχεται να χρησιμοποιεί διαφορετική κλίμακα βαθμολογίας.",
    "Courses": "Μαθήματα",
    "Course name": "Όνομα μαθήματος",
    "Course name (optional)": "Όνομα μαθήματος (προαιρετικό)",
    "Letter grade": "Βαθμός (γράμμα)",
    "Credits": "Διδακτικές μονάδες",
    "Remove course": "Αφαίρεση μαθήματος",
    "Add course": "Προσθήκη μαθήματος",
    "Calculate GPA": "Υπολογισμός Μ.Ο. βαθμολογίας (GPA)",
