    "Weighted GPA": "Σταθμισμένος Μ.Ο. βαθμολογίας",
    "Add your courses and credits.": "Προσθέστε τα μαθήματα και τις διδακτικές μονάδες σας.",
    "A+ and A both count as 4.0 on this scale.": "Τα A+ και A υπολογίζονται ως 4,0 σε αυτή την κλίμακα.",
    "Choose a file (up to 25 MB)": "Επιλογή αρχείου (έως 25 MB)",
    "Your file is processed on this device and is not uploaded.": "Το αρχείο σας επεξεργάζεται στη συσκευή σας και δεν μεταφορτώνεται σε διακομιστή.",
    "Create SHA-256 checksum": "Δημιουργία αθροίσματος ελέγχου SHA-256",
    "Choose a file to begin.": "Επιλέξτε ένα αρχείο για να ξεκινήσετε.",
    "SHA-256 checksum": "Άθροισμα ελέγχου SHA-256",
    "The checksum will appear here...": "Το άθροισμα ελέγχου θα εμφανιστεί εδώ...",
    "Copy checksum": "Αντιγραφή αθροίσματος ελέγχου",
    "Compare with a known checksum (optional)": "Σύγκριση με γνωστό άθροισμα ελέγχου (προαιρετικά)",
    "Paste the published SHA-256 value": "Επικόλληση της δημοσιευμένης τιμής SHA-256",
    "Choose an image (up to 20 MB)": "Επιλογή εικόνας (έως 20 MB)",
    "JPG, PNG or WebP. Your original is never changed.": "JPG, PNG ή WebP. Το πρωτότυπο αρχείο σας δεν τροποποιείται ποτέ.",
    "Width (px)": "Πλάτος (px)",
    "Keep proportions": "Διατήρηση αναλογιών",
    "Height (px)": "Ύψος (px)",
    "Output format": "Μορφή εξόδου",
    "Quality applies to JPEG and WebP. PNG is lossless.": "Η ρύθμιση ποιότητας αφορά τα JPEG και WebP. Το PNG είναι χωρίς απώλειες.",
    "Resize and save image": "Αλλαγή μεγέθους και αποθήκευση εικόνας",
    "The image is processed locally in your browser.": "Η εικόνα επεξεργάζεται τοπικά στο πρόγραμμα περιήγησής σας.",
    "Download image": "Λήψη εικόνας",
    "What do you want to do?": "Τι θέλετε να κάνετε;",
    "Merge PDF files": "Συγχώνευση αρχείων PDF",
    "Extract page ranges": "Εξαγωγή εύρους σελίδων",
    "Compress a PDF (image-based)": "Συμπίεση PDF (με βάση εικόνες)",
    "Choose PDF file(s) (up to 10 MB each)": "Επιλογή αρχείου(-ων) PDF (έως 10 MB το καθένα)",
    "PDF files stay on this device. Choose up to 10 files.": "Τα αρχεία PDF παραμένουν σε αυτή τη συσκευή. Επιλέξτε έως 10 αρχεία.",
    "Page ranges (for example: 1-3, 5-7)": "Εύρος σελίδων (π.χ. 1-3, 5-7)",
    "Each range becomes a separate PDF file.": "Κάθε εύρος γίνεται ξεχωριστό αρχείο PDF.",
    "Important before you continue": "Σημαντικές πληροφορίες πριν συνεχίσετε",
    "Pages become images. Text will not be selectable and links, forms and signatures are not kept. The new file can be larger than the original.": "Οι σελίδες μετατρέπονται σε εικόνες. Το κείμενο δεν θα είναι επιλέξιμο και δεν διατηρούνται σύνδεσμοι, φόρμες και υπογραφές. Το νέο αρχείο ενδέχεται να είναι μεγαλύτερο από το αρχικό.",
    "I understand. Keep my original PDF.": "Κατανοώ. Διατήρηση του αρχικού PDF.",
    "PDF processing runs in this browser. No upload.": "Η επεξεργασία PDF γίνεται εδώ, χωρίς μεταφόρτωση.",
    "Choose a CSV file (up to 5 MB)": "Επιλογή αρχείου CSV (έως 5 MB)",
    "The file opens locally and is not uploaded.": "Το αρχείο ανοίγει τοπικά και δεν μεταφορτώνεται.",
    "Search table": "Αναζήτηση στον πίνακα",
    "Search all columns": "Αναζήτηση σε όλες τις στήλες",
    "Choose a CSV file to see its table.": "Επιλέξτε ένα αρχείο CSV για να δείτε τον πίνακα που περιέχει.",
    "Table pages": "Σελίδες πίνακα",
    "Choose a QR image": "Επιλογή εικόνας QR",
    "The image is scanned on your device. Nothing is uploaded.": "Η εικόνα σαρώνεται στη συσκευή σας. Δεν γίνεται μεταφόρτωση δεδομένων.",
    "Start camera": "Ενεργοποίηση κάμερας",
    "Stop camera": "Διακοπή κάμερας",
    "Camera access is optional. You will be asked before it starts.": "Η πρόσβαση στην κάμερα είναι προαιρετική. Θα ερωτηθείτε πριν ξεκινήσει.",
    "QR code contents": "Περιεχόμενα κωδικού QR",
    "Scanned text will appear here...": "Το κείμενο που σαρώθηκε θα εμφανιστεί εδώ...",
    "Open safe link": "Άνοιγμα ασφαλούς συνδέσμου",
    "Pass": "Επιτυχία",
    "Does not pass": "Αποτυχία",
    "Continue": "Συνέχεια",
    "Previous": "Προηγούμενο",
    "Next": "Επόμενο",
    "Calculate tip": "Υπολογισμός φιλοδωρήματος",
    "Open link": "Άνοιγμα συνδέσμου",
    "XML input exceeds the 2 MB limit. Process a smaller document.": "Η είσοδος XML υπερβαίνει το όριο των 2 MB. Επεξεργαστείτε ένα μικρότερο έγγραφο.",
