    "Convert file": "Μετατροπή αρχείου",
    "Some characters need your browser fonts. In the print window, choose Save as PDF.": "Ορισμένοι χαρακτήρες απαιτούν τις γραμματοσειρές του προγράμματος περιήγησής σας. Στο παράθυρο εκτύπωσης, επιλέξτε «Αποθήκευση ως PDF».",
    "Choose a fillable PDF": "Επιλέξτε συμπληρώσιμο PDF",
    "Draw a visual signature (optional)": "Σχεδίαση υπογραφής (προαιρετικό)",
    "Signature drawing area": "Περιοχή σχεδίασης υπογραφής",
