    "Open ZIP": "Άνοιγμα ZIP",
    "Choose files or a ZIP archive": "Επιλέξτε αρχεία ή αρχείο ZIP",
    "Up to 200 files and 250 MB expanded data. ZIP64 and password-protected files are not supported.": "Έως 200 αρχεία και 250 MB δεδομένων μετά την αποσυμπίεση. Δεν υποστηρίζονται αρχεία ZIP64 και αρχεία προστατευμένα με κωδικό πρόσβασης.",
    "Files are not uploaded.": "Τα αρχεία δεν μεταφορτώνονται στον διακομιστή.",
    "Output": "Έξοδος",
    "MP3 audio": "Ήχος MP3",
    "M4A / AAC audio": "Ήχος M4A / AAC",
    "OGG / Opus audio": "Ήχος OGG / Opus",
    "MP4 video": "Βίντεο MP4",
    "Choose a portrait image": "Επιλέξτε μια φωτογραφία πορτρέτου",
    "Start background removal": "Έναρξη αφαίρεσης φόντου",
    "The first use loads about 6.6 MB from this site. The photo is processed on your device. A computer is recommended for large images.": "Κατά την πρώτη χρήση φορτώνονται περίπου 6,6 MB από αυτόν τον ιστότοπο. Η επεξεργασία της φωτογραφίας γίνεται στη συσκευή σας. Για μεγάλες φωτογραφίες συνιστάται η χρήση υπολογιστή.",
    "Transparent PNG preview": "Προεπισκόπηση PNG με διαφάνεια",
