    "Choose an image first.": "Επιλέξτε πρώτα μια φωτογραφία.",
    "Ready to remove the background.": "Έτοιμο για αφαίρεση φόντου.",
    "Portrait image must be 20 megapixels or smaller. Resize it before processing.": "Η φωτογραφία πορτρέτου πρέπει να είναι 20 megapixel ή μικρότερη. Αλλάξτε το μέγεθός της πριν από την επεξεργασία.",
    "Background removal complete. Review the edges before using the image.": "Η αφαίρεση φόντου ολοκληρώθηκε. Ελέγξτε τα περιγράμματα πριν χρησιμοποιήσετε τη φωτογραφία.",
    "WebM video": "Βίντεο WebM",
    "Start (seconds)": "Έναρξη (δευτερόλεπτα)",
