    "End of file": "Τέλος αρχείου",
    "Save large output directly to disk (supported browsers)": "Αποθήκευση μεγάλου όγκου αποτελεσμάτων απευθείας στον δίσκο (υποστηριζόμενα προγράμματα περιήγησης)",
    "Expression": "Έκφραση",
    "Supports arithmetic, powers, percentages, trigonometry, roots and logarithms.": "Υποστηρίζει αριθμητικές πράξεις, δυνάμεις, ποσοστά, τριγωνομετρία, ρίζες και λογαρίθμους.",
    "Use radians (otherwise degrees)": "Χρήση ακτινίων (διαφορετικά μοίρες)",
