    "Choose a file": "Επιλογή αρχείου",
    "Office files stay on your device. Layout, formulas, charts, animations, fonts and page breaks may change. Office to PDF opens your browser’s print dialog. Use a computer for large files.": "Τα αρχεία Office παραμένουν στη συσκευή σας. Η διάταξη, οι τύποι, τα γραφήματα, τα κινούμενα γραφικά, οι γραμματοσειρές και οι αλλαγές σελίδας ενδέχεται να αλλάξουν. Η λειτουργία Office σε PDF ανοίγει το παράθυρο διαλόγου εκτύπωσης του προγράμματος περιήγησής σας. Χρησιμοποιήστε υπολογιστή για μεγάλα αρχεία.",
    "PDF to Excel estimates rows from selectable text; it does not recreate formulas or tables. PDF to PowerPoint makes image-only slides. Scanned PDFs need OCR first.": "Η μετατροπή PDF σε Excel υπολογίζει τις γραμμές με βάση το επιλέξιμο κείμενο· δεν αναδημιουργεί τύπους ή πίνακες. Η μετατροπή PDF σε PowerPoint δημιουργεί διαφάνειες που αποτελούνται μόνο από εικόνες. Τα σαρωμένα PDF απαιτούν προηγούμενη επεξεργασία OCR.",
    "Office print view opened. Check it, then choose Save as PDF in the browser.": "Άνοιξε η προβολή εκτύπωσης του Office. Ελέγξτε την και, στη συνέχεια, επιλέξτε «Αποθήκευση ως PDF» στο πρόγραμμα περιήγησης.",
    "The converted file is ready. Review the result and keep the original.": "Το μετατρεμμένο αρχείο είναι έτοιμο. Ελέγξτε το αποτέλεσμα και διατηρήστε το πρωτότυπο αρχείο.",
