    "Convert time": "Μετατροπή ώρας",
    "Uses your browser’s time zone data, including daylight saving changes.": "Χρησιμοποιεί τα δεδομένα ζώνης ώρας του προγράμματος περιήγησής σας, συμπεριλαμβανομένων των αλλαγών για τη θερινή ώρα.",
