    "No speech detected. Try clearer audio or choose a language.": "Δεν εντοπίστηκε ομιλία. Δοκιμάστε καθαρότερο ήχο ή επιλέξτε γλώσσα.",
    "Copied to clipboard.": "Αντιγράφηκε στο πρόχειρο.",
