    "Text file downloaded.": "Το αρχείο κειμένου λήφθηκε.",
    "This file or codec could not be processed. Try another supported format.": "Δεν ήταν δυνατή η επεξεργασία αυτού του αρχείου ή του codec. Δοκιμάστε άλλη υποστηριζόμενη μορφή.",
    "For long or high-resolution media, a desktop or laptop is recommended. Keep this tab open; speed, memory and battery depend on your device.": "Για αρχεία πολυμέσων μεγάλης διάρκειας ή υψηλής ανάλυσης, συνιστάται η χρήση επιτραπέζιου ή φορητού υπολογιστή. Διατηρήστε αυτή την καρτέλα ανοιχτή· η ταχύτητα, η μνήμη και η μπαταρία εξαρτώνται από τη συσκευή σας.",
    "Re-encoding can reduce sound quality or make a larger file. Your original stays unchanged.": "Η επανακωδικοποίηση ενδέχεται να μειώσει την ποιότητα του ήχου ή να δημιουργήσει μεγαλύτερο αρχείο. Το πρωτότυπο αρχείο σας παραμένει αμετάβλητο.",
    "First use downloads about 58 MB of model and local engine. Your recording is not uploaded; the browser may download them again if its cache is cleared.": "Κατά την πρώτη χρήση, πραγματοποιείται λήψη περίπου 58 MB για το μοντέλο και την τοπική μηχανή επεξεργασίας. Η εγγραφή σας δεν μεταφορτώνεται στον διακομιστή· το πρόγραμμα περιήγησης ενδέχεται να τα κατεβάσει ξανά εάν διαγραφεί η προσωρινή μνήμη (cache) του.",
    "Your file is processed locally and is not uploaded.": "Το αρχείο σας υποβάλλεται σε επεξεργασία τοπικά και δεν μεταφορτώνεται στον διακομιστή.",
