    "Extract selectable PDF text into Markdown with page headings. Scanned pages must be OCR-processed first; page layout and tables are not preserved.": "Εξαγωγή επιλέξιμου κειμένου PDF σε μορφή Markdown με επικεφαλίδες σελίδων. Οι σαρωμένες σελίδες πρέπει πρώτα να υποβληθούν σε επεξεργασία OCR· η διάταξη της σελίδας και οι πίνακες δεν διατηρούνται.",
    "Extracts selectable text page by page. Scanned pages need OCR first; layout, tables and images are not preserved. Your file stays on this device.": "Εξάγει επιλέξιμο κείμενο ανά σελίδα. Οι σαρωμένες σελίδες απαιτούν πρώτα OCR· η διάταξη, οι πίνακες και οι εικόνες δεν διατηρούνται. Το αρχείο σας παραμένει στη συσκευή.",
