      "intro": "Δεν χρειάζεται να μετατρέψετε έναν δεκαεξαδικό αριθμό πρώτα σε δεκαδικό. Αντικαταστήστε κάθε δεκαεξαδικό ψηφίο με το αντίστοιχο δυαδικό του ισοδύναμο τεσσάρων bit και, στη συνέχεια, ενώστε τις ομάδες με τη σωστή σειρά.",
