              "type": "p",
              "text": "Το δεκαεξαδικό σύστημα χρησιμοποιεί δεκαέξι σύμβολα: 0–9 και A–F, όπου το A αντιστοιχεί στο 10 και το F στο 15. Τέσσερα δυαδικά ψηφία (bits) μπορούν να αναπαραστήσουν τιμές από το 0 έως το 15, επομένως κάθε δεκαεξαδικό ψηφίο αντιστοιχεί ακριβώς σε μία ομάδα τεσσάρων δυαδικών ψηφίων."
